import * as THREE from 'three';
document.addEventListener('DOMContentLoaded', function () {
  const e = new THREE.Scene(),
    n = new THREE.PerspectiveCamera(
      75,
      window.innerWidth / window.innerHeight,
      0.1,
      1e3
    ),
    o = new THREE.WebGLRenderer();
  (o.setSize(window.innerWidth, window.innerHeight),
    document.body.appendChild(o.domElement));
  const t = new THREE.BoxGeometry(1, 1, 1),
    i = new THREE.MeshBasicMaterial({ color: 65280 }),
    d = new THREE.Mesh(t, i);
  (e.add(d),
    (n.position.z = 5),
    o.setAnimationLoop(function (t) {
      ((d.rotation.x = t / 2e3), (d.rotation.y = t / 1e3), o.render(e, n));
    }));
});
